window.__PIXEL_CHAOS__={get formation(){return formation;},get battle(){return battle;},get mode(){return mode;},renderer};
// Inspection uses the same rounded model, not a separate illustration.
const descriptions={beam:'Disparo de energia concentrada.',volley:'Rajada tripla de energia.',missiles:'Salva de seis mísseis guiados.',spell:'Feitiço que imobiliza o alvo.',punch:'Soco com grande dano e arremesso.',aard:'Onda de choque que afasta os inimigos.',chidori:'Investida elétrica que interrompe o alvo.',explosion:'Detonação em área com arremesso.',lightning:'Explosão de raios com interrupção.',rasengan:'Rasengan com dano de área e clones visuais temporários.',stretch:'Soco elástico de grande alcance que empurra os inimigos.',void:'Explosão de energia roxa, lentidão e proteção temporária.',slash:'Onda cortante que atravessa a linha inimiga.',water:'Corte circular de água e breve redução de dano.',force:'Dano concentrado que imobiliza o alvo por 1,6 segundos.',heal:'Cura aliados próximos e afasta inimigos com a Força.',web:'Teias que imobilizam e deixam o grupo mais lento.',ice:'Explosão de gelo que causa dano e lentidão em área.',psychic:'Onda telecinética que arremessa e interrompe inimigos.',shadow:'Mãozinha ataca o alvo; Wandinha ganha proteção temporária.'};
let inspectRenderer,inspectScene,inspectCamera,inspectModel,inspectAngle=0,inspectFX,inspectProjectiles,previewBattle=null,previewTime=0,previewTarget;
function drawInspection(){if(!inspectRenderer||!inspectModel)return;inspectModel.rotation.y=inspectAngle;inspectRenderer.render(inspectScene,inspectCamera);}
$('inspect').onclick=()=>{
 if(battle)return;
 if(!inspectRenderer){inspectRenderer=new T.WebGLRenderer({canvas:$('modelCanvas'),alpha:true,antialias:true});inspectRenderer.setPixelRatio(Math.min(devicePixelRatio,1.5));inspectRenderer.outputColorSpace=T.SRGBColorSpace;inspectScene=new T.Scene();inspectScene.add(new T.HemisphereLight(0xe2f6ff,0x45404c,2.5));const light=new T.DirectionalLight(0xffe4cb,3);light.position.set(-3,6,4);inspectScene.add(light);inspectFX=new AbilityFX(inspectScene);inspectFX.high=true;inspectProjectiles=new ProjectileRenderer(inspectScene);previewTarget=new T.Mesh(new T.CapsuleGeometry(.24,.8,4,10),new T.MeshLambertMaterial({color:0x647b86}));previewTarget.position.set(0,.65,3);previewTarget.visible=false;inspectScene.add(previewTarget);inspectCamera=new T.PerspectiveCamera(36,1,.1,30);}
 previewBattle=null;if(inspectFX)inspectFX.clear();if(inspectProjectiles)inspectProjectiles.sync([]);if(previewTarget)previewTarget.visible=false;if(inspectModel){inspectScene.remove(inspectModel);disposeCharacter(inspectModel);}
 inspectModel=character(selected,'blue',selectedGod);inspectModel.userData.bar.visible=inspectModel.userData.barBack.visible=false;inspectScene.add(inspectModel);inspectAngle=.25;
 const d=TYPES[selected];$('inspectName').textContent=d.name+(selectedGod?' GOD':'');$('inspectDescription').textContent=`${d.series} · ${d.power}. ${descriptions[d.ability]||d.power}.${selectedGod?' GOD: '+godDescription(selected):''}`;$('inspectStats').textContent=`${d.hp} PV · ${d.damage} ATQ · ${unitCost(selected,selectedGod)} moedas`;
 $('inspectDialog').showModal();const rect=$('modelCanvas').getBoundingClientRect();inspectRenderer.setSize(rect.width,rect.height,false);inspectCamera.aspect=rect.width/rect.height;inspectCamera.fov=36;inspectCamera.position.set(0,1.7,5.6);inspectCamera.lookAt(0,1.4,0);inspectCamera.updateProjectionMatrix();drawInspection();
};
$('rotateModel').onclick=()=>{inspectAngle+=Math.PI/4;drawInspection();};
let inspectDrag=null;$('modelCanvas').onpointerdown=e=>{inspectDrag=e.clientX;$('modelCanvas').setPointerCapture(e.pointerId);};$('modelCanvas').onpointermove=e=>{if(inspectDrag===null)return;inspectAngle+=(e.clientX-inspectDrag)*.02;inspectDrag=e.clientX;drawInspection();};$('modelCanvas').onpointerup=$('modelCanvas').onpointercancel=()=>inspectDrag=null;

$('testSkill').onclick=()=>{
 if(!inspectFX)return;inspectFX.clear();inspectProjectiles.sync([]);previewTime=0;
 previewBattle=new Battle([{type:selected,god:selectedGod,team:'blue',x:0,z:0},{type:'saitama',team:'red',x:0,z:3}],e=>{if(e.type==='charge')inspectFX.charge(e);if(e.type==='cancel')inspectFX.cancel(e.unit);if(e.type==='special')inspectFX.release(e);if(e.type==='impact')inspectFX.impact(e);if(e.type==='dash')inspectFX.dash(e);},()=>.5);
 const [u,target]=previewBattle.units;u.cool=u.special=target.cool=target.special=Infinity;target.hp=target.maxHp=1e9;target.stun=999;u.angle=0;
 previewBattle.beginCast(u,target);inspectAngle=0;inspectModel.rotation.y=0;previewTarget.visible=true;inspectCamera.fov=42;inspectCamera.position.set(4.8,3.5,7.5);inspectCamera.lookAt(0,1.25,1.3);inspectCamera.updateProjectionMatrix();skillAudio.play(selected,'charge',sound);
};
function updateAbilityPreview(dt){
 if(!previewBattle||!$('inspectDialog').open)return;previewTime+=dt;const [u,target]=previewBattle.units;target.stun=999;const charging=!!u.casting;previewBattle.step(Math.min(dt,.04));if(charging&&!u.casting)skillAudio.play(selected,'release',sound);
 inspectModel.position.set(u.x,0,u.z);const d=inspectModel.userData;if(u.casting||u.releaseTime>0){const phase=u.casting?'charge':'release',p=u.casting?1-u.casting.remaining/u.casting.duration:1-u.releaseTime/(u.releaseDuration||1),pose=castPose(selected,phase,p);d.arms.forEach((arm,i)=>arm.rotation.x=pose.arms[i]);d.forearms.forEach((arm,i)=>arm.rotation.x=pose.forearms[i]);d.body.rotation.set(pose.bodyX,pose.bodyY,pose.bodyZ);}
 previewTarget.position.set(target.x,.65+(target.lift>0?Math.sin((1.6-target.lift)/1.6*Math.PI)*1.4:0),target.z);inspectFX.update(dt);inspectProjectiles.sync(previewBattle.projectiles);drawInspection();
 if(previewTime>ABILITIES[selected].charge+3){previewBattle=null;inspectFX.clear();inspectProjectiles.sync([]);drawInspection();}
}
$('inspectDialog').addEventListener('close',()=>{previewBattle=null;if(inspectFX)inspectFX.clear();if(inspectProjectiles)inspectProjectiles.sync([]);});
